import sqlparse


def _ident(s):
    return sqlparse.parse(s)[0].tokens[0]


def test_real_name_four_parts():
    assert _ident('db.schema.tbl.col').get_real_name() == 'col'


def test_real_name_three_parts():
    assert _ident('a.b.c').get_real_name() == 'c'


def test_real_name_two_parts_unchanged_and_three_parts_fixed():
    assert _ident('a.b').get_real_name() == 'b'
    assert _ident('a').get_real_name() == 'a'
    assert _ident('a.b.c').get_real_name() == 'c'


def test_parent_name_first_real_name_last():
    p = _ident('db.schema.tbl.col')
    assert p.get_parent_name() == 'db'
    assert p.get_real_name() == 'col'


def test_real_name_three_parts_quoted():
    p = _ident('"db"."my schema"."tbl"')
    assert p.get_real_name() == 'tbl'
    assert p.get_parent_name() == 'db'


def test_real_name_three_parts_with_as_alias():
    p = _ident('a.b.c AS d')
    assert p.get_real_name() == 'c'
    assert p.get_alias() == 'd'
    assert p.get_name() == 'd'


def test_real_name_three_parts_with_alias_without_as():
    p = _ident('a.b.c d')
    assert p.get_real_name() == 'c'
    assert p.get_alias() == 'd'


def test_get_name_three_parts_without_alias():
    assert _ident('a.b.c').get_name() == 'c'


def test_real_name_three_parts_wildcard():
    assert _ident('a.b.*').get_real_name() == '*'


def test_real_name_three_parts_inside_statement():
    p = sqlparse.parse('select a.b.c from x.y.z')[0]
    assert p.tokens[2].get_real_name() == 'c'
    assert p.tokens[6].get_real_name() == 'z'

