import datetime
import unittest

from . import tomllib


class TestOptionalSeconds(unittest.TestCase):
    def test_local_time_without_seconds(self):
        self.assertEqual(tomllib.loads("t = 13:37"), {"t": datetime.time(13, 37)})

    def test_local_time_without_seconds_boundaries(self):
        self.assertEqual(tomllib.loads("t = 00:00"), {"t": datetime.time(0, 0)})
        self.assertEqual(tomllib.loads("t = 23:59"), {"t": datetime.time(23, 59)})

    def test_local_datetime_without_seconds(self):
        self.assertEqual(
            tomllib.loads("dt = 1979-05-27T07:32"),
            {"dt": datetime.datetime(1979, 5, 27, 7, 32)},
        )

    def test_local_datetime_without_seconds_space_separator(self):
        self.assertEqual(
            tomllib.loads("dt = 1979-05-27 07:32"),
            {"dt": datetime.datetime(1979, 5, 27, 7, 32)},
        )

    def test_offset_datetime_without_seconds_zulu(self):
        self.assertEqual(
            tomllib.loads("dt = 1979-05-27 07:32Z"),
            {
                "dt": datetime.datetime(
                    1979, 5, 27, 7, 32, tzinfo=datetime.timezone.utc
                )
            },
        )

    def test_offset_datetime_without_seconds_numeric_offset(self):
        tz = datetime.timezone(datetime.timedelta(hours=-7))
        actual = tomllib.loads("dt = 1979-05-27 07:32-07:00")["dt"]
        self.assertEqual(actual, datetime.datetime(1979, 5, 27, 7, 32, tzinfo=tz))
        self.assertEqual(actual.utcoffset(), datetime.timedelta(hours=-7))

    def test_without_seconds_in_array_and_inline_table(self):
        self.assertEqual(
            tomllib.loads("a = [07:32, 1979-05-27T07:32]\nb = {t = 08:15}"),
            {
                "a": [datetime.time(7, 32), datetime.datetime(1979, 5, 27, 7, 32)],
                "b": {"t": datetime.time(8, 15)},
            },
        )

    def test_without_seconds_then_comment(self):
        self.assertEqual(
            tomllib.loads("t = 07:32 # comment\n"), {"t": datetime.time(7, 32)}
        )

    def test_with_seconds_still_parsed(self):
        # Runs after a no-seconds parse so that this test fails on a
        # parser that still requires seconds.
        doc = "a = 07:32\nb = 07:32:01\nc = 07:32:01.5\nd = 1979-05-27T07:32:01.25Z"
        self.assertEqual(
            tomllib.loads(doc),
            {
                "a": datetime.time(7, 32),
                "b": datetime.time(7, 32, 1),
                "c": datetime.time(7, 32, 1, 500000),
                "d": datetime.datetime(
                    1979, 5, 27, 7, 32, 1, 250000, tzinfo=datetime.timezone.utc
                ),
            },
        )

    def test_fraction_without_seconds_is_invalid(self):
        # Sanity check that the no-seconds form is accepted at all, so
        # that this test fails on a parser that still requires seconds.
        self.assertEqual(tomllib.loads("t = 07:32"), {"t": datetime.time(7, 32)})
        for doc in ("t = 07:32.5", "dt = 1979-05-27T07:32.5"):
            with self.subTest(doc=doc):
                with self.assertRaises(tomllib.TOMLDecodeError):
                    tomllib.loads(doc)

    def test_malformed_without_seconds_is_invalid(self):
        self.assertEqual(tomllib.loads("t = 07:32"), {"t": datetime.time(7, 32)})
        for doc in (
            "t = 07:32:",  # trailing colon
            "t = 07:3",  # one digit minute
            "t = 7:32",  # one digit hour
            "t = 24:00",  # hour out of range
            "t = 07:60",  # minute out of range
            "t = 07",  # hours only
            "dt = 1979-05-27T07",  # hours only
            "dt = 1979-05-27T07:32:",  # trailing colon
        ):
            with self.subTest(doc=doc):
                with self.assertRaises(tomllib.TOMLDecodeError):
                    tomllib.loads(doc)

