import unittest

from . import tomllib


class TestInlineTableNewlinesAndTrailingComma(unittest.TestCase):
    def test_trailing_comma(self):
        self.assertEqual(tomllib.loads("t = {a = 1, b = 2,}"), {"t": {"a": 1, "b": 2}})
        self.assertEqual(tomllib.loads("t = { a = 1 , }"), {"t": {"a": 1}})

    def test_newlines_between_pairs(self):
        doc = "t = {\n  a = 1,\n  b = 2\n}\n"
        self.assertEqual(tomllib.loads(doc), {"t": {"a": 1, "b": 2}})

    def test_newlines_and_trailing_comma(self):
        doc = "t = {\n  a = 1,\n  b = 2,\n}\nafter = true\n"
        self.assertEqual(tomllib.loads(doc), {"t": {"a": 1, "b": 2}, "after": True})

    def test_newline_before_comma(self):
        doc = "t = {a = 1\n, b = 2}"
        self.assertEqual(tomllib.loads(doc), {"t": {"a": 1, "b": 2}})

    def test_crlf_newlines(self):
        doc = "t = {\r\n  a = 1,\r\n  b = 2,\r\n}\r\n"
        self.assertEqual(tomllib.loads(doc), {"t": {"a": 1, "b": 2}})

    def test_empty_inline_table_with_newlines(self):
        self.assertEqual(tomllib.loads("t = {\n}"), {"t": {}})
        self.assertEqual(tomllib.loads("t = {\n\n  \t\n}"), {"t": {}})

    def test_comments_inside_inline_table(self):
        doc = (
            "t = { # opening\n"
            "  a = 1, # after a\n"
            "  # own line\n"
            "  b = 2 # before close\n"
            "}\n"
        )
        self.assertEqual(tomllib.loads(doc), {"t": {"a": 1, "b": 2}})

    def test_nested_multiline(self):
        doc = (
            "t = {\n"
            "  inner = {\n"
            "    x = 1,\n"
            "  },\n"
            "  arr = [\n"
            "    { y = 2, },\n"
            "  ],\n"
            "}\n"
        )
        self.assertEqual(
            tomllib.loads(doc), {"t": {"inner": {"x": 1}, "arr": [{"y": 2}]}}
        )

    def test_comma_only_is_invalid(self):
        for doc in ("t = {,}", "t = {\n,\n}", "t = {,\n}"):
            with self.subTest(doc=doc):
                with self.assertRaises(tomllib.TOMLDecodeError):
                    tomllib.loads(doc)

    def test_double_comma_is_invalid(self):
        for doc in ("t = {a = 1,,}", "t = {a = 1,\n,\n}", "t = {a = 1,, b = 2}"):
            with self.subTest(doc=doc):
                with self.assertRaises(tomllib.TOMLDecodeError):
                    tomllib.loads(doc)

    def test_missing_comma_across_newline_is_invalid(self):
        with self.assertRaises(tomllib.TOMLDecodeError):
            tomllib.loads("t = {\n  a = 1\n  b = 2\n}")

    def test_unclosed_multiline_is_invalid(self):
        for doc in ("t = {\n", "t = {\n  a = 1,\n", "t = {a = 1,"):
            with self.subTest(doc=doc):
                with self.assertRaises(tomllib.TOMLDecodeError):
                    tomllib.loads(doc)

    def test_newline_around_equals_is_invalid(self):
        for doc in ("t = {a\n= 1}", "t = {a =\n1}"):
            with self.subTest(doc=doc):
                with self.assertRaises(tomllib.TOMLDecodeError):
                    tomllib.loads(doc)

    def test_duplicate_key_across_lines_is_invalid(self):
        with self.assertRaises(tomllib.TOMLDecodeError):
            tomllib.loads("t = {\n  a = 1,\n  a = 2,\n}")

    def test_inner_inline_table_stays_immutable(self):
        with self.assertRaises(tomllib.TOMLDecodeError):
            tomllib.loads("t = {\n  a = {x = 1},\n  a.y = 2,\n}")
